#!/usr/bin/env bash\nset -euo pipefail\n\n# Default backup directory inside the user's home\nBACKUP_ROOT="${HOME}/.dotfile_backups"\n# List of dotfiles to manage – can be overridden via DOTFILE_LIST env var\nDOTFILES="${DOTFILE_LIST:-.bashrc .vimrc .gitconfig}"\n\nusage() {\n  cat <<'EOF'\ndotchronicle - Manage timestamped snapshots of your dotfiles.\n\nUsage:\n  dotchronicle backup          Create a new backup of configured dotfiles.\n  dotchronicle list            List existing backups.\n  dotchronicle restore <id>    Restore dotfiles from backup with given timestamp ID.\nEOF\n}\n\nbackup() {\n  timestamp=$(date +"%Y%m%d_%H%M%S")\n  dest="${BACKUP_ROOT}/${timestamp}"\n  mkdir -p "${dest}"\n  for file in ${DOTFILES}; do\n    src="${HOME}/${file}"\n    if [[ -e "${src}" ]]; then\n      cp -p "${src}" "${dest}/"\n    fi\n  done\n  echo "Backup created at ${timestamp}"\n}\n\nlist_backups() {\n  if [[ ! -d "${BACKUP_ROOT}" ]]; then\n    echo "No backups found."\n    exit 0\n  fi\n  ls -1 "${BACKUP_ROOT}" | sort\n}\n\nrestore() {\n  local id="$1"\n  src="${BACKUP_ROOT}/${id}"\n  if [[ ! -d "${src}" ]]; then\n    echo "Backup ${id} not found."\n    exit 1\n  fi\n  for file in ${DOTFILES}; do\n    backup_file="${src}/${file##*/}"\n    if [[ -e "${backup_file}" ]]; then\n      cp -p "${backup_file}" "${HOME}/${file}"\n    fi\n  done\n  echo "Restored backup ${id}"\n}\n\nif [[ $# -lt 1 ]]; then\n  usage\n  exit 1\nfi\n\ncmd="$1"\nshift\ncase "${cmd}" in\n  backup) backup ;;\n  list) list_backups ;;\n  restore)\n    if [[ $# -lt 1 ]]; then\n      echo "restore requires a backup ID"\n      usage\n      exit 1\n    fi\n    restore "$1"\n    ;;\n  *)\n    echo "Unknown command: ${cmd}"\n    usage\n    exit 1\n    ;;\nesac\n
